"""Template passive monodomain manufactured fields on the unit square; <name>(x, y, t) for Vm and S.  Generated by template_mms.py."""

import numpy

# module: template

PARAMS = {'CHI': 3.0, 'CM': 2.0, 'SIGMA': [0.13, 0.0176]}


def Vm(x, y, t):
    _ref = numpy.zeros(numpy.broadcast(x, y, t).shape)
    return (numpy.sqrt(t + 1)*numpy.cos(numpy.pi*x)*numpy.cos(numpy.pi*y)) + _ref


def S(x, y, t):
    _ref = numpy.zeros(numpy.broadcast(x, y, t).shape)
    _t0 = t + 1
    return ((3/2500)*(123*numpy.pi**2*_t0 + 2500)*numpy.cos(numpy.pi*x)*numpy.cos(numpy.pi*y)/numpy.sqrt(_t0)) + _ref
